          "text": "今天的方法叫情绪辨认与陪伴。从发生的事情和表情辨认感受，这叫情绪辨认。听听朋友的需要，再陪伴他。比如，塔倒了可能难过，朋友想安静时可以坐在旁边。我们一起看一看，再试一试。",
