      "plannedSeconds": 1200,
      "status": "ready",
      "opening": [
        {
          "id": "LA6-02-O01",
          "text": "侦探社收到一张奇怪的清单：红色或蓝色，而且不能是圆形。米米说，这次符合条件的礼物可能不止一件。",
          "action": "朋友提出今天的问题，展示材料与情境。"
        }
      ],
      "teaching": [
        {
          "id": "LA6-02-K01",
          "text": "今天的方法叫多条件筛选，包含与排除。根据所有线索找齐符合条件的物品，叫多条件筛选。既看要包含什么，也看要排除什么。比如，要方形但不要绿色，红方片和蓝方片都符合条件。我们一起看一看，再试一试。",
          "action": "先说出概念名称，再把名称和图中具体对象对应。",
          "visualStep": 0
        },
        {
          "id": "LA6-02-T01",
          "text": "红色或蓝色都可以先留下来。这个线索给了两种可能，不是要求一件东西同时有两种颜色。",
          "action": "关键对象移动、比较或改变条件，观察前后结果。",
          "visualStep": 0
        },
        {
          "id": "LA6-02-T02",
          "text": "再看不能是圆形。把圆片排除，红方片和蓝方片都可以符合条件。",
          "action": "关键对象移动、比较或改变条件，观察前后结果。",
          "visualStep": 1
        },
        {
          "id": "LA6-02-T03",
          "text": "检查每件候选，不能找到第一件就停。换一条排除条件后，还要重新检查刚才留下的物品。",
          "action": "关键对象移动、比较或改变条件，观察前后结果。",
          "visualStep": 2
        }
      ],
      "film": [
        {
          "id": "LA6-02-F01",
          "text": "点点戴上侦探帽，认真地说，今天要找一位方方的客人。",
          "action": "第 1 幕：点点戴上侦探帽，认真地说，今天要找一位方方的客人。"
        },
        {
          "id": "LA6-02-F02",
          "text": "帽檐下却滑出一张圆纸片，落在他的鼻尖。",
          "action": "第 2 幕：帽檐下却滑出一张圆纸片，落在他的鼻尖。"
        },
        {
          "id": "LA6-02-F03",
          "text": "米米先不收进盒子，指着纸片的边绕一圈。",
          "action": "第 3 幕：米米先不收进盒子，指着纸片的边绕一圈。"
        },
        {
          "id": "LA6-02-F04",
          "text": "小鸟把方标签送来，点点这才看看圆片，再看看方片。",
          "action": "第 4 幕：小鸟把方标签送来，点点这才看看圆片，再看看方片。"
        },
        {
          "id": "LA6-02-F05",
          "text": "两张标签各回到自己的小袋里，侦探帽也终于戴稳。",
          "action": "第 5 幕：两张标签各回到自己的小袋里，侦探帽也终于戴稳。"
        },
        {
          "id": "LA6-02-F06",
          "text": "点点笑着记下第一条提醒：先检查线索，再把客人请进来。",
          "action": "第 6 幕：点点笑着记下第一条提醒：先检查线索，再把客人请进来。"
        }
      ],
