      "plannedSeconds": 1200,
      "status": "ready",
      "opening": [
        {
          "id": "LA6-08-O01",
          "text": "米米和点点都想玩同一只小车，只有一只。点点刚拿到，米米也很期待。怎样把两位的请求都放进计划呢？",
          "action": "朋友提出今天的问题，展示材料与情境。"
        }
      ],
      "teaching": [
        {
          "id": "LA6-08-K01",
          "text": "今天的方法叫轮流与协商。大家按约定先后使用同一件物品，叫轮流。一起商量先后和等待办法，叫协商。比如，先由一位朋友玩，之后交换，等待时也听听对方的想法。我们一起看一看，再试一试。",
          "action": "先说出概念名称，再把名称和图中具体对象对应。",
          "visualStep": 0
        },
        {
          "id": "LA6-08-T01",
          "text": "先问对方想怎样玩，再说明自己的请求。抢过来很快，却没有照顾另一位的需要。",
          "action": "关键对象移动、比较或改变条件，观察前后结果。",
          "visualStep": 0
        },
        {
          "id": "LA6-08-T02",
          "text": "可以商量一人完成一段小路后交换，也可以用轮流卡约定谁先谁后。规则要让双方都知道并愿意。",
          "action": "关键对象移动、比较或改变条件，观察前后结果。",
          "visualStep": 1
        },
        {
          "id": "LA6-08-T03",
          "text": "约定以后还要兑现。轮到朋友时交出去，今天不想参加也可以另选活动，不强迫一直等待。",
          "action": "关键对象移动、比较或改变条件，观察前后结果。",
          "visualStep": 2
        }
      ],
      "film": [
        {
          "id": "LA6-08-F01",
          "text": "点点把小车开到树下，米米在另一边挥挥手。",
          "action": "第 1 幕：点点把小车开到树下，米米在另一边挥挥手。"
        },
        {
          "id": "LA6-08-F02",
          "text": "小车中间停住，像也在等一个清楚的安排。",
          "action": "第 2 幕：小车中间停住，像也在等一个清楚的安排。"
        },
        {
          "id": "LA6-08-F03",
          "text": "米米摆出一张小卡，先送信到树下，再换司机。",
          "action": "第 3 幕：米米摆出一张小卡，先送信到树下，再换司机。"
        },
        {
          "id": "LA6-08-F04",
          "text": "点点到树下，把小车轻轻推给米米，没有再绕一圈。",
          "action": "第 4 幕：点点到树下，把小车轻轻推给米米，没有再绕一圈。"
        },
        {
          "id": "LA6-08-F05",
          "text": "米米把一片叶子放上车，开回朋友身边。",
          "action": "第 5 幕：米米把一片叶子放上车，开回朋友身边。"
        },
        {
          "id": "LA6-08-F06",
          "text": "小鸟看看来回的小路。车只有一只，故事却有两位司机。",
          "action": "第 6 幕：小鸟看看来回的小路。车只有一只，故事却有两位司机。"
        }
      ],
