          "text": "今天的方法叫按数量分装，数量增减。每份按照订单数量装好，叫按数量分装。添上与拿走叫数量增减。订单可以不同，不要求平均分。比如，一份五个，一份三个，要分别数清；花去代币后，再数剩余。我们一起看一看，再试一试。",
